package net.officefloor.hq.app.claim;

/**
 * Where a claim is in its life: DRAFT, then OPEN, then SETTLED. A clerk settling an OPEN claim whose due is above the
 * clerk limit sends it to PENDING instead, which a steward approves (SETTLED) or rejects (back to OPEN). A DRAFT, OPEN
 * or PENDING claim may be VOID; a steward may also void a SETTLED one shortly after its settlement (see ClaimService).
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim in this status may move to the next one by opening, settling or voiding it. */
    public boolean canMoveTo(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || isOpen();
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status counts toward claimed and the totals. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is handled as open: it goes overdue, bears the late charge, and a hold takes it out of the totals. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
  watched: boolean;
}

/** A hold of a person from its from-date to its to-date (yyyy-mm-dd), both inclusive; to null: it does not end. */
interface PersonHold {
  from: string;
  to: string | null;
}

/** Whether the date is within any of the holds. */
function heldOn(holds: PersonHold[], date: string): boolean {
  return holds.some((h) => h.from <= date && (h.to === null || date <= h.to));
}

/**
 * Whether the claim counts in the live totals: an OPEN, PENDING or SETTLED one, but an OPEN or PENDING one dated within
 * a hold of its person not unless a statement binds it, and one deferred on the sheet's today not at all.
 */
function live(claim: Claim, holds: PersonHold[], today: string | null): boolean {
  return counts(claim, today) && !(isOpen(claim) && !bound(claim) && heldOn(holds, claim.date));
}

/**
 * Whether the claim counts in a period's due-total: by the status it had at the end of the period's last day, an OPEN,
 * PENDING or SETTLED one, but one open then and still open now and dated within a hold of its person not unless a
 * statement binds it, and one deferred on the sheet's today not at all.
 */
function liveAtEnd(claim: Claim, holds: PersonHold[], today: string | null, end: string): boolean {
  const status = statusOn(claim, end);
  if (status === null || deferred(claim, today)) return false;
  const open = status === 'OPEN' || status === 'PENDING';
  return (open || status === 'SETTLED') && !(open && isOpen(claim) && !bound(claim) && heldOn(holds, claim.date));
}

/** A CSV field: wrapped in double quotes, any quote inside doubled, when it holds a comma, a quote or a line break. */
function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

