export function isCorrection(claim: Claim): boolean {
  return claim.amount.trim().startsWith('-') && /[1-9]/.test(claim.amount);
}

/**
 * Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED ones do, but not one deferred on
 * the sheet's today.
 */
export function counts(claim: Claim, today: string | null): boolean {
  return (isOpen(claim) || claim.status === 'SETTLED') && !deferred(claim, today);
}

/**
 * Whether the claim is deferred on the sheet's today: an OPEN claim deferred until a later date. It then counts in no
 * total, is not overdue, cannot be settled and is left unbound by a statement.
 */
export function deferred(claim: Claim, today: string | null): boolean {
  return claim.status === 'OPEN' && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
}

/**
 * The status the claim had at the end of the date, as its status log records it: its last line logged on or before
 * the date; null when it has lines but none by then (it was added later). With no log at all, its status now.
 */
export function statusOn(claim: Claim, date: string): ClaimStatus | null {
  if (claim.log.length === 0) return claim.status;
  let found: ClaimStatus | null = null;
  for (const line of claim.log) if (line.date <= date) found = line.status;
  return found;
}
    @Transactional
    public Person take(String sheetId, String user, Long personId) {
        Person person = people.findForUpdate(personId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Sheet sheet = sheets.get(sheetId);
        LocalDate today = sheet.getToday();
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        // As on the screen: n/a when the grade in force today has no rate today, unless a counting claim has a fixed due
        // or a due on or before today.
        boolean anyDue = rates.rateOn(sheetId, person.gradeOn(today), today).isPresent();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int counted = 0;
        for (Claim claim : theirs) {
            if (!person.counts(claim, today)) {
                claim.setStated(false, null);
                continue;
            }
            counted++;
            if (claim.getSettledDue() != null || claim.getBoundDue() != null) {
                anyDue = true;
            }
            // The statement binds the rate figure under the claim's due; its late charge keeps following the sheet's
            // today, and the floor is applied last.
            BigDecimal figure = figureOf(sheetId, person, claim).orElse(null);
            BigDecimal due = claim.getSettledDue() != null || claim.isCorrection() ? figure
                    : sheet.floored(sheet.withLateCharge(figure, claim.getStatus().isOpen(), claim.getDueBy(),
                            claim.getDate()), claim.getDate());
            if (due != null) {
                total = total.add(due);
                // A due under a grade the person had on an earlier date counts too.

